import{_ as e,c as a,o,ae as r}from"./chunks/framework.CDjunVez.js";const g=JSON.parse('{"title":"Privacy Policy for Universal Scanner","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),i={name:"privacy.md"};function n(s,t,l,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="privacy-policy-for-universal-scanner" tabindex="-1">Privacy Policy for Universal Scanner <a class="header-anchor" href="#privacy-policy-for-universal-scanner" aria-label="Permalink to &quot;Privacy Policy for Universal Scanner&quot;">​</a></h1><p><strong>Effective Date:</strong> 21st December 2025</p><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><p><strong>Universal Scanner</strong> (&quot;we,&quot; &quot;our,&quot; or &quot;us&quot;) operates the Universal Scanner mobile application (the &quot;App&quot;). We are committed to protecting your privacy and providing you with a clear, granular understanding of how your data is handled. This policy explains <strong>exactly</strong> what data we collect, why we collect it, how it is stored, and your rights.</p><p>By using the App, you agree to the collection and use of information in accordance with this policy.</p><h2 id="_2-data-we-collect-specific-permissions" tabindex="-1">2. Data We Collect &amp; Specific Permissions <a class="header-anchor" href="#_2-data-we-collect-specific-permissions" aria-label="Permalink to &quot;2. Data We Collect &amp; Specific Permissions&quot;">​</a></h2><h3 id="_2-1-device-permissions-hardware-access" tabindex="-1">2.1 Device Permissions (Hardware Access) <a class="header-anchor" href="#_2-1-device-permissions-hardware-access" aria-label="Permalink to &quot;2.1 Device Permissions (Hardware Access)&quot;">​</a></h3><p>To function as a barcode and QR code scanner, the App requires specific hardware permissions.</p><ul><li><p><strong>Camera Permission:</strong></p><ul><li><strong>Purpose:</strong> To scan 1D and 2D barcodes in real-time. We use <strong>advanced on-device machine learning</strong> to process the scanned barcodes locally. The image data <strong>never leaves your device</strong> and is not transmitted to any server.</li><li><strong>Granularity:</strong> We access the camera video stream strictly for the duration of the &quot;Scan&quot; mode. The video frames are processed <strong>locally</strong> on your device&#39;s processor using state-of-the-art embedded computer vision algorithms.</li><li><strong>Privacy:</strong> We <strong>do not</strong> record, save, store, or transmit the video feed or images to any external server. The video stream is discarded immediately after <strong>processing locally</strong>.</li></ul></li><li><p><strong>Photo Library Access (Optional):</strong></p><ul><li><strong>Purpose:</strong> To allow you to scan a barcode from a static image saved in your gallery.</li><li><strong>Granularity:</strong> We only access the <strong>specific single image</strong> you manually select via the system picker. We do not scan, index, or upload your entire photo library.</li></ul></li><li><p><strong>Flashlight/Torch:</strong></p><ul><li><strong>Purpose:</strong> To illuminate barcodes in low-light environments.</li><li><strong>Granularity:</strong> Controlled manually by the user via the UI toggle.</li></ul></li></ul><h3 id="_2-2-usage-data-analytics-anonymous" tabindex="-1">2.2 Usage Data &amp; Analytics (Anonymous) <a class="header-anchor" href="#_2-2-usage-data-analytics-anonymous" aria-label="Permalink to &quot;2.2 Usage Data &amp; Analytics (Anonymous)&quot;">​</a></h3><p>We collect completely <strong>anonymous</strong>, aggregated telemetry data to improve app stability and user experience. We use <strong>PostHog</strong> for this purpose.</p><p><strong>Specific Data Points Collected:</strong></p><ul><li><strong>Device Attributes:</strong><ul><li>Device Model (e.g., iPhone 13, Pixel 6)</li><li>Operating System Version (e.g., iOS 17.2, Android 14)</li><li>App Version (e.g., v1.2.0)</li><li>Screen Resolution and Density</li></ul></li><li><strong>Usage Interaction:</strong><ul><li><strong>Screen Views:</strong> Which screens are visited (e.g., &quot;SettingsScreen&quot;, &quot;HistoryScreen&quot;).</li><li><strong>Feature Actions:</strong> Interactions such as &quot;Scan Completed&quot;, &quot;Flashlight Toggled&quot;, &quot;Batch Mode Enabled&quot;, &quot;Export to PDF&quot;.</li><li><strong>Session Metrics:</strong> Duration of app usage and frequency of sessions.</li></ul></li><li><strong>Diagnostics:</strong><ul><li><strong>Crash Logs:</strong> Stack traces generated if the app crashes (helps us identify and fix bugs).</li><li><strong>Performance:</strong> App startup time and scan processing speed (aggregated).</li></ul></li></ul><p><strong>What We DO NOT Collect:</strong></p><ul><li><strong>No Personal Identity:</strong> We do not collect your name, email address, phone number, or physical address.</li><li><strong>No Scan Content:</strong> We do not collecting the <strong>content</strong> of your scans (e.g., we know a scan happened, but we don&#39;t know <em>what</em> text or URL was scanned) in our analytics.</li><li><strong>No Location:</strong> We do not track your precise GPS location.</li></ul><h2 id="_3-how-we-use-your-data" tabindex="-1">3. How We Use Your Data <a class="header-anchor" href="#_3-how-we-use-your-data" aria-label="Permalink to &quot;3. How We Use Your Data&quot;">​</a></h2><p>We use the collected data for the following specific purposes:</p><ul><li><strong>Core Functionality:</strong> To decode barcodes and display the results to you.</li><li><strong>App Improvement:</strong> To analyze which features are popular and need refinement (e.g., if &quot;Batch Scan&quot; is used often, we might improve its UI).</li><li><strong>Stability:</strong> To monitor crash rates and fix technical issues promptly.</li><li><strong>Legal Compliance:</strong> To comply with applicable laws and regulations.</li></ul><h2 id="_4-third-party-service-providers" tabindex="-1">4. Third-Party Service Providers <a class="header-anchor" href="#_4-third-party-service-providers" aria-label="Permalink to &quot;4. Third-Party Service Providers&quot;">​</a></h2><p>We use the following trusted third-party service provider. Data shared with them is anonymous and aggregated.</p><h3 id="posthog-analytics" tabindex="-1">PostHog Analytics <a class="header-anchor" href="#posthog-analytics" aria-label="Permalink to &quot;PostHog Analytics&quot;">​</a></h3><ul><li><strong>Purpose:</strong> Product analytics and feature usage tracking.</li><li><strong>Data Shared:</strong> Anonymous device IDs, event logs (interactions), and technical device details.</li><li><strong>Processing Location:</strong> Data may be processed in the United States or EU depending on server configuration.</li><li><strong>Privacy Policy:</strong> <a href="https://posthog.com/privacy" target="_blank" rel="noreferrer">PostHog Privacy Policy</a></li></ul><h3 id="international-data-transfers" tabindex="-1">International Data Transfers <a class="header-anchor" href="#international-data-transfers" aria-label="Permalink to &quot;International Data Transfers&quot;">​</a></h3><p>Your information, including analytics data, may be transferred to — and maintained on — computers located outside of your state, province, country, or other governmental jurisdiction where the data protection laws may differ than those from your jurisdiction.</p><p>By using the App, you consent to this transfer. We will take all steps reasonably necessary to ensure that your data is treated securely and in accordance with this Privacy Policy.</p><h2 id="_5-data-retention-storage" tabindex="-1">5. Data Retention &amp; Storage <a class="header-anchor" href="#_5-data-retention-storage" aria-label="Permalink to &quot;5. Data Retention &amp; Storage&quot;">​</a></h2><h3 id="local-data-on-your-device" tabindex="-1">Local Data (On Your Device) <a class="header-anchor" href="#local-data-on-your-device" aria-label="Permalink to &quot;Local Data (On Your Device)&quot;">​</a></h3><ul><li><strong>Scan History:</strong> All scanned barcodes, generated codes, and associated metadata (timestamps, formats) are stored in a local database <strong>on your device</strong>.</li><li><strong>Retention:</strong> This data remains on your device until you manually delete specific items or uninstall the App. <strong>We have zero access to this database.</strong></li></ul><h3 id="analytics-data-cloud" tabindex="-1">Analytics Data (Cloud) <a class="header-anchor" href="#analytics-data-cloud" aria-label="Permalink to &quot;Analytics Data (Cloud)&quot;">​</a></h3><ul><li><strong>Retention:</strong> Anonymous logs are retained for a limited period (typically 90 days) to allow for trend analysis, after which they are automatically deleted or aggregated.</li></ul><h2 id="_6-data-security" tabindex="-1">6. Data Security <a class="header-anchor" href="#_6-data-security" aria-label="Permalink to &quot;6. Data Security&quot;">​</a></h2><p>We implement robust security measures to protect your data:</p><ul><li><strong>Local Encryption:</strong> The App uses secure sandbox storage provided by the operating system (iOS/Android) to prevent unauthorized access to your local history.</li><li><strong>Transmission Security:</strong> All analytics data transmitted to our service providers is encrypted using <strong>TLS/SSL (Transport Layer Security)</strong>.</li><li><strong>Minimization:</strong> We practice data minimization by only collecting data that is strictly necessary for the App&#39;s function.</li></ul><h2 id="_7-your-rights-gdpr-ccpa-cpra-global" tabindex="-1">7. Your Rights (GDPR, CCPA, CPRA &amp; Global) <a class="header-anchor" href="#_7-your-rights-gdpr-ccpa-cpra-global" aria-label="Permalink to &quot;7. Your Rights (GDPR, CCPA, CPRA &amp; Global)&quot;">​</a></h2><p>Regardless of your location, we extend these rights to all users:</p><ul><li><p><strong>No Sale of Data (Including Unidentifiable Info):</strong></p><ul><li><strong>Strict Policy:</strong> Since we do not collect personal information, we have no personal information to sell. Furthermore, we <strong>do not sell, trade, or share</strong> your <strong>anonymous or unidentifiable</strong> usage data with third parties for their direct marketing purposes or any other commercial benefit.</li><li><strong>Clarification:</strong> Our use of third-party analytics (PostHog) strictly involves service provider relationships where data use is limited to functioning and improving the App on our behalf.</li></ul></li><li><p><strong>Right to Opt-Out (Do Not Sell or Share My Info):</strong></p><ul><li>Although we do not sell your data, you retain the right to opt-out of all tracking and analytics processing. You can exercise this right directly:</li><li><strong>Do Not Track (DNT) Signals:</strong> We do not track you over time and across third-party websites to provide targeted advertising and therefore do not respond to Do Not Track (DNT) signals.</li><li><strong>Action:</strong> Go to <strong>Settings &gt; Privacy &gt; Analytics</strong> and toggle the switch to <strong>OFF</strong>. This will strictly prevent any data transmission to our analytics providers.</li></ul></li><li><p><strong>Right to Access:</strong> You can view your locally stored scan history directly within the &quot;History&quot; tab of the App.</p></li><li><p><strong>Right to Erasure (Deletion):</strong></p><ul><li><strong>Local Data:</strong> You can delete individual scans or clear your entire history in <strong>Settings &gt; Clear All History</strong>.</li><li><strong>Analytics:</strong> You can request the deletion of your anonymous analytics profile by contacting us with your installation ID (found in Settings &gt; Diagnostics).</li></ul></li><li><p><strong>Right to Portability:</strong> You can export your scan history data to CSV, PDF, or JSON formats directly from the App.</p></li></ul><h2 id="_8-external-links" tabindex="-1">8. External Links <a class="header-anchor" href="#_8-external-links" aria-label="Permalink to &quot;8. External Links&quot;">​</a></h2><p>The App may generate or scan QR codes containing links to third-party websites. If you click on a link, you will be directed to that third party&#39;s site. We strongly advise you to review the Privacy Policy of every site you visit. We have no control over and assume no responsibility for the content, privacy policies, or practices of any third-party sites or services.</p><h2 id="_9-children-s-privacy" tabindex="-1">9. Children’s Privacy <a class="header-anchor" href="#_9-children-s-privacy" aria-label="Permalink to &quot;9. Children’s Privacy&quot;">​</a></h2><p>Our Services do not address anyone under the age of 13. We do not knowingly collect personally identifiable information from children under 13. If you are a parent or guardian and you are aware that your child has provided us with personal information, please contact us so that we will be able to do necessary actions.</p><h2 id="_10-changes-to-this-privacy-policy" tabindex="-1">10. Changes to This Privacy Policy <a class="header-anchor" href="#_10-changes-to-this-privacy-policy" aria-label="Permalink to &quot;10. Changes to This Privacy Policy&quot;">​</a></h2><p>We may update our Privacy Policy from time to time. Thus, you are advised to review this page periodically for any changes. We will notify you of any changes by posting the new Privacy Policy on this page. These changes are effective immediately after they are posted.</p><h2 id="_11-contact-us" tabindex="-1">11. Contact Us <a class="header-anchor" href="#_11-contact-us" aria-label="Permalink to &quot;11. Contact Us&quot;">​</a></h2><p>If you have any questions or suggestions about our Privacy Policy, do not hesitate to contact us at:</p><p><strong>Email:</strong> <a href="mailto:cranbear.service@gmail.com" target="_blank" rel="noreferrer">cranbear.service@gmail.com</a></p><h2 id="_12-version-history" tabindex="-1">12. Version History <a class="header-anchor" href="#_12-version-history" aria-label="Permalink to &quot;12. Version History&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Version</th><th style="text-align:left;">Date</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">1.0</td><td style="text-align:left;">2025-12-21</td><td style="text-align:left;">Initial Privacy Policy release.</td></tr></tbody></table>',47)])])}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
